/**
 * ground.ts — shared machinery for the Bun-grounding pipeline.
 *
 * Truth hierarchy (P0+P1 refactor, see docs/BUN_GROUNDED.md):
 *   1. pinned bun-types@1.4.0, TS-parsed structurally -> tools/bun-shape.json
 *   2. official bun.com docs (llms.txt-indexed; URLs validated live)
 *   3. consolidated probe registry (tools/ground-probes) — runtime assertions
 * The manifest (tools/bun-grounding.json) and docs/BUN_GROUNDED.md are
 * GENERATED by `bun run ground`; `bun run ground:check` verifies them live.
 * Never hand-edit generated outputs.
 */

// ── shape (pinned bun-types, TS-parsed) ─────────────────────────────────────

export interface ShapeMember {
  name: string;
  ns: string;
  kind: string;
  typeOnly: boolean;
  docs: boolean;
  deprecated: boolean;
  extension: boolean;
}

export interface BunShape {
  bunVersion: string;
  bunRevision: string;
  pinnedVersion: string;
  generatedAt: string;
  members: ShapeMember[];
}

export const SHAPE_PATH = "tools/bun-shape.json";
export const MANIFEST_PATH = "tools/bun-grounding.json";
export const GROUNDED_DOC_PATH = "docs/BUN_GROUNDED.md";
export const DOCS_INDEX = "https://bun.com/docs/llms.txt";

export async function loadShape(root: string): Promise<BunShape> {
  return (await Bun.file(root + "/" + SHAPE_PATH).json()) as BunShape;
}

export function shapeLookup(shape: BunShape): Map<string, ShapeMember> {
  const m = new Map<string, ShapeMember>();
  for (const member of shape.members) {
    m.set(member.ns ? member.ns + "." + member.name : member.name, member);
  }
  return m;
}

// ── usage scan (repo -> Bun.* tokens) ───────────────────────────────────────

const TOKEN_RE = /Bun\.[A-Za-z_$][A-Za-z0-9_$]*(?:\.[A-Za-z_$][A-Za-z0-9_$]*)?/g;
// src/tools/scripts only — test fixtures would pollute the manifest.
const SCAN_DIRS = ["src", "tools", "scripts"];

/** rg scan of the repo source dirs -> token -> count. Offline. */
export function scanBunTokens(root: string): Map<string, number> {
  const counts = new Map<string, number>();
  const proc = Bun.spawnSync([
    "rg", "-o", "Bun\\.[A-Za-z_$][A-Za-z0-9_$]*(?:\\.[A-Za-z_$][A-Za-z0-9_$]*)?",
    ...SCAN_DIRS, "--no-filename", "-g", "!*.json",
  ], { cwd: root, stdout: "pipe", stderr: "pipe" });
  const out = proc.stdout.toString();
  if (out.length === 0) return counts;
  for (const match of out.match(/\S+/g) ?? []) {
    counts.set(match, (counts.get(match) ?? 0) + 1);
  }
  return counts;
}

/**
 * Resolve a repo token ("Bun.XML.parse", "Bun.file") against the shape:
 * longest ns.name match, else top-level name, else null.
 */
export function resolveToken(token: string, lookup: Map<string, ShapeMember>): ShapeMember | null {
  const parts = token.split("."); // ["Bun", "XML", "parse"]
  const dotted = parts.slice(1).join(".");
  if (lookup.has(dotted)) return lookup.get(dotted)!;
  const top = parts[1] ?? "";
  return lookup.get(top) ?? null;
}

