export function docsUrlFor(member: ShapeMember): string {
  const url = DOCS_URL[member.name] ?? (member.ns ? DOCS_URL[member.ns] : undefined);
  return url ?? "https://bun.com/docs/runtime";
}

// ── stale-URL detection (the /docs/api/* scheme is dead; blocklist is 404s) ──

export const STALE_URL_PATTERNS: RegExp[] = [
  /bun\.com\/docs\/api\//, // whole /docs/api/* tree redirects/404s
  /bun\.com\/docs\/runtime\/api\b/, // 404
  /bun\.com\/docs\/runtime\/bun-write\b/, // 404 (guide moved into file-io)
  /bun\.com\/docs\/runtime\/bun-secrets\b/, // 404 (page is /docs/runtime/secrets)
  /bun\.com\/docs\/runtime\/websockets\b/, // 404 (page is /docs/runtime/http/websockets)
  /bun\.com\/docs\/runtime\/postgres\b/, // 404 (page is /docs/runtime/sql)
  /bun\.com\/docs\/runtime\/terminal\b/, // 404 (Terminal lives in utils/reference)
];

/** Scan a blob of text for stale bun.com doc URLs. */
export function findStaleUrls(text: string): string[] {
  const found: string[] = [];
  for (const re of STALE_URL_PATTERNS) {
    const m = text.match(re);
    if (m) found.push(m[0]);
  }
  return [...new Set(found)];
}

// ── manifest schema ──────────────────────────────────────────────────────────

export interface GroundRow {
  symbol: string;
  name: string;
  ns: string;
  kind: string;
  typeOnly: boolean;
  /** typeof Bun.<top> !== "undefined" on the installed runtime (offline check). */
  runtime: boolean;
  used: boolean;
  usageCount: number;
  docsUrl: string;
  gate: string;
  probeWired: boolean;
}

export interface GroundManifest {
  bunVersion: string;
  shapeRevision: string;
  generatedAt: string;
  generator: string;
  shapeFile: string;
  docsIndex: string;
  rows: GroundRow[];
  unknownTokens: string[];
  staleUrlCount: number;
}

/** Normalize a gateFor() result: strip " (ns)", map GAP to "". */
export function normalizeGate(raw: string): string {
  const g = raw.replace(/\s+\(ns\)$/, "");
  return g === "GAP" || g === "undefined" ? "" : g;
}

/**
 * Known false-positive tokens (types, module namespaces, CLI flags and
 * metasyntactic examples in comments/docs) — filtered out of the manifest's
 * unknownTokens list so real drift stays visible.
 */
export const UNKNOWN_TOKEN_ALLOWLIST: ReadonlySet<string> = new Set([
  "Bun.File", "Bun.Args", "Bun.CSV", "Bun.Request", "Bun.SourceMap", "Bun.Shell", // type-only / doc names
  "Bun.Foo", "Bun.X", "Bun.S", "Bun.x", "Bun.term", "Bun.tok", // metasyntactic / truncated
  "Bun.ffi", "Bun.Networking", "Bun.Quic", // module namespaces (bun:ffi), not Bun.* members
  "Bun.gzip", "Bun.zstd", "Bun.rename", "Bun.watch", "Bun.map", "Bun.html", // CLI flags / prose
  "Bun.image", "Bun.isTerminal", "Bun.fullName", "Bun.dimension", "Bun.readableStreamTo", // prose / partial names
]);
